CREATE TABLE IF NOT EXISTS public.support_tickets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),ticket_number TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE,customer_name TEXT,subject TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'General',description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','waiting_customer','resolved','closed')),priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_support_tickets_customer_updated ON public.support_tickets(customer_id,updated_at DESC); CREATE INDEX IF NOT EXISTS idx_support_tickets_status_updated ON public.support_tickets(status,updated_at DESC); CREATE TABLE IF NOT EXISTS public.support_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id UUID NOT NULL REFERENCES public.support_tickets(id) ON DELETE CASCADE,author_role TEXT NOT NULL CHECK(author_role IN ('customer','admin')),message TEXT NOT NULL,is_internal BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_support_messages_ticket_created ON public.support_messages(ticket_id,created_at); ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;